ALTER SESSION SET CONTAINER = FREEPDB1;
SET SERVEROUTPUT ON SIZE UNLIMITED
DECLARE
  v_ok NUMBER := 0;
  v_miss NUMBER := 0;
  v_err NUMBER := 0;
BEGIN
  FOR r IN (SELECT column_value AS table_name FROM TABLE(SYS.DBMS_DEBUG_VC2COLL('SCM_ADM_API_M','SCM_ADM_CMBO_SQL_M','SCM_ADM_DQ_COLUMN','SCM_ADM_DQ_COLUMN_H','SCM_ADM_DQ_EXECUTE_H','SCM_ADM_DQ_LIST','SCM_ADM_DQ_LIST_H','SCM_ADM_DQ_PARAMETER','SCM_ADM_DQ_PARAMETER_H','SCM_ADM_DQ_USER_GROUP','SCM_ADM_DQ_USER_GROUP_H','SCM_ADM_EXCEL_COLUMNS','SCM_ADM_EXCEL_UPLOAD','SCM_ADM_LOOKUP_MASTER','SCM_ADM_LOOKUP_MASTER_DETAIL','SCM_ADM_LOOKUP_MASTER_DETAIL_BAK','SCM_ADM_LOOKUP_MASTER_DETAIL_H','SCM_ADM_LOOKUP_MASTER_H','SCM_ADM_MNU_BTN_MPG_M','SCM_ADM_MNU_M','SCM_ADM_MNU_M_20260413','SCM_ADM_MSG_M','SCM_ADM_NOTICE_CONFIRM','SCM_ADM_NOTICE_CONFIRM_H','SCM_ADM_NOTICE_CONTENT_MASTER','SCM_ADM_NOTICE_CONTENT_MASTER_H','SCM_ADM_NOTICE_MASTER','SCM_ADM_NOTICE_MASTER_H','SCM_ADM_PROC_M','SCM_ADM_RECIPIENT_ASSIGN','SCM_ADM_RECIPIENT_ASSIGN_H','SCM_ADM_RECIPIENT_LIST','SCM_ADM_RECIPIENT_LIST_H','SCM_ADM_RECIPIENT_MESSAGE','SCM_ADM_RECIPIENT_MESSAGE_H','SCM_ADM_RECIPIENT_SMS_ASSIGN','SCM_ADM_RECIPIENT_SMS_GROUP','SCM_ADM_SMS_MAIL_SEND_LOG','SCM_ADM_USER_BMK_M','SCM_ADM_USER_GR_M','SCM_ADM_USER_GR_MNU_BTN_MPG_M','SCM_ADM_USER_GR_MNU_MPG_M','SCM_ADM_USER_GR_MPG_M','SCM_ADM_USER_GR_UNIT_AUTH_MPG_M','SCM_ADM_USER_M','SCM_ADM_USER_MNU_SRCH_COND_M','SCM_CODE_LOOKUP_VALUE','SCM_COM_ATCH_FILE_M','SCM_ITEM_M','SCM_MST_ALTER_BOM','SCM_MST_ALTER_BOM_H','SCM_MST_ALTER_BOM_MODEL','SCM_MST_AUTH_REQUEST','SCM_MST_BOD_ENG','SCM_MST_BOD_ITEM_ENG','SCM_MST_BUCKET','SCM_MST_CITY','SCM_MST_COMPANY_SN','SCM_MST_COUNTRY','SCM_MST_CUSTOMER','SCM_MST_CUSTOMER_H','SCM_MST_DIVISION','SCM_MST_FUTURE_PRICE','SCM_MST_FUTURE_PRICE_C','SCM_MST_FUTURE_PRICE_H','SCM_MST_ITEM_CLASS_M','SCM_MST_LINE_OSP','SCM_MST_LINE_OSP_H','SCM_MST_LOCATION','SCM_MST_LOCATION_H','SCM_MST_MODEL_BOM_EFFECTIVE','SCM_MST_MODELING','SCM_MST_OSP_SLOC','SCM_MST_OSP_SLOC_H','SCM_MST_PLAN','SCM_MST_PLAN_DETAIL','SCM_MST_PLAN_FP_RELEASE_ID','SCM_MST_PROJECT','SCM_MST_PROJECT_H','SCM_MST_PROJECT_ITEM','SCM_MST_PROJECT_ITEM_H','SCM_MST_PROJECT_MAPPING','SCM_MST_PROJECT_MAPPING_H','SCM_MST_PROJECT_MODEL_DEMAND_QTY','SCM_MST_PROJECT_MODEL_DEMAND_QTY_H','SCM_MST_PROJECT_SCHEDULE','SCM_MST_PROJECT_SCHEDULE_H','SCM_MST_PROJECTBOM','SCM_MST_SHEET_COLUMNS','SCM_MST_SHEET_MEASURE','SCM_MST_SITE','SCM_MST_SITE_CUSTOMER','SCM_MST_SITE_CUSTOMER_H','SCM_MST_SITE_ENG','SCM_MST_SITE_H','SCM_MST_SITE_ITEM','SCM_MST_SITE_ITEM_ENG','SCM_MST_SITE_ITEM_H','SCM_MST_SITE_ITEM_PRIORITY','SCM_MST_SITE_ITEM_PRIORITY_H','SCM_MST_SLOC','SCM_MST_SLOC_H','SCM_MST_SSO_DEPT_INFO','SCM_MST_SSO_USER_INFO','SCM_MST_TITLESET_USER','SCM_MST_VENDOR','SCM_MST_VENDOR_H','SCM_MST_VMI_INT_SLOC','SCM_SHIP_ALLO_REPORT','SCM_SIM_DYN_COLS','SCM_SYS_CALENDAR_M','SCM_SYS_LOG_BATCH','SCM_SYS_LOG_BATCH_INF'))) LOOP
    DECLARE
      v_cnt NUMBER;
    BEGIN
      SELECT COUNT(*) INTO v_cnt FROM dba_tables WHERE owner='SCM_MGR' AND table_name=r.table_name;
      IF v_cnt = 0 THEN
        v_miss := v_miss + 1;
        DBMS_OUTPUT.PUT_LINE('MISS: '||r.table_name);
      ELSE
        EXECUTE IMMEDIATE 'DELETE FROM SCM_MGR.'||r.table_name;
        v_ok := v_ok + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1;
      DBMS_OUTPUT.PUT_LINE('ERR: '||r.table_name||' - '||SQLERRM);
    END;
  END LOOP;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Deleted='||v_ok||', Missing='||v_miss||', Error='||v_err);
END;
/
EXIT
